// Turn the comma-separated Config strings into the arrays the actor expects.
const cfg = $json;
const ALLOWED = ['google', 'youtube', 'amazon', 'bing'];

const keywords = String(cfg.seedKeywords || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const sources = String(cfg.sources || 'google')
  .split(',').map((s) => s.trim().toLowerCase()).filter((s) => ALLOWED.includes(s));

if (!keywords.length) throw new Error('Config > seedKeywords is empty — add at least one seed keyword.');
if (!sources.length) throw new Error('Config > sources has no valid entries — use any of: google, youtube, amazon, bing.');

return [{ json: { keywords, sources, gl: String(cfg.country || '').trim().toLowerCase() } }];

// One dataset row per seed -> one sheet row per idea.
// Success rows look like: { seed, sources, expand, count, suggestions: [...] }
// Seeds with no results come back as { seed, error, errorType } — never charged, skipped here.
const out = [];
const date = new Date().toISOString().slice(0, 10);

for (const { json: row } of $input.all()) {
  if (!Array.isArray(row.suggestions)) continue; // error/no-results row
  const sources = Array.isArray(row.sources) ? row.sources.join(', ') : String(row.sources || '');
  for (const idea of row.suggestions) {
    if (!idea) continue;
    out.push({ json: { seed: row.seed, idea, sources, date } });
  }
}

return out;
